document.querySelectorAll('.local-enquiry-form').forEach(form=>{form.addEventListener('submit',event=>{event.preventDefault();const d=new FormData(form);const text=`CROWNWING PARROTS — LOCATION ENQUIRY\nCity: ${form.dataset.city}\nName: ${d.get('name')}\nEmail: ${d.get('email')}\nSpecies: ${d.get('species')}\n\n${d.get('message')}\n\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`crownwing-${form.dataset.city.toLowerCase().replace(/[^a-z]+/g,'-')}-enquiry.txt`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);form.querySelector('.local-form-status').textContent='Your enquiry copy is ready to download.'})});
